import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AnalyticsDashboard() {
  const [totalDeliveries, setTotalDeliveries] = useState(0);
  const [activeDrivers, setActiveDrivers] = useState(0);
  const [successRate, setSuccessRate] = useState("0%");

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const deliveriesRes = await axios.get("http://localhost:5000/api/delivery");
        const driversRes = await axios.get("http://localhost:5000/api/drivers");

        const deliveries = deliveriesRes.data;
        const drivers = driversRes.data;

        const deliveredCount = deliveries.filter((d) => d.status === "Delivered").length;
        const totalCount = deliveries.length;

        setTotalDeliveries(totalCount);
        setActiveDrivers(drivers.filter((d) => d.isAvailable).length);
        setSuccessRate(
          totalCount > 0 ? `${Math.round((deliveredCount / totalCount) * 100)}%` : "0%"
        );
      } catch (err) {
        console.error("Error fetching analytics data", err);
      }
    };

    fetchStats();
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Analytics Dashboard</h2>
      <div style={{ marginTop: "20px" }}>
        <p><strong>Total Deliveries:</strong> {totalDeliveries}</p>
        <p><strong>Active Drivers:</strong> {activeDrivers}</p>
        <p><strong>Success Rate:</strong> {successRate}</p>
      </div>
    </div>
  );
}
